std::vector data = {1, 2, 3, 4, 5};

// Full container reversal
std::reverse(data.begin(), data.end());
// data == {5, 4, 3, 2, 1}

// Partial range reversal (elements 4, 3, 2)
auto start = data.begin() + 2; // Iterator to element 3
auto end = data.end() - 1;     // Iterator before element 1
std::reverse(start, end);
// data == {5, 4, 2, 3, 1}

// Range reversal using rbegin/rend (reverse direction)
std::reverse(data.rbegin(), data.rend());
// data == {1, 3, 2, 4, 5}
